const { existsSync, readFileSync } = await import('node:fs');
const pngPath = process.env.PNG_PATH;
if (!pngPath) { throw new Error('Missing PNG_PATH env var'); }
if (!existsSync(pngPath)) { throw new Error(`PNG file not found at ${pngPath}`); }
const data = readFileSync(pngPath);
globalThis.pngBase64 = data.toString('base64');
const outEnv = process.env.OUTPUT_PATH;
globalThis.outputPath = outEnv || pngPath.replace(/\\.png$/i, '.pdf');

const { jsPDF } = await import('jspdf');
const pdf = new jsPDF();
// Add the image at full page size (A4 default 210x297 mm). Adjust as needed.
pdf.addImage(globalThis.pngBase64, 'PNG', 0, 0);
const arrayBuf = pdf.output('arraybuffer');
const { writeFileSync } = await import('node:fs');
writeFileSync(globalThis.outputPath, Buffer.from(arrayBuf));
